const classifyTaskDB=[{"w":"Andrew Heywood","gen":"Fuente","n":"El plano general de las siete familias","g":"«Political Ideologies», muchas ediciones","t":"Manual académico, sólido como manual"},{"w":"John Stuart Mill","gen":"Fuente","n":"La libertad en el núcleo del liberalismo","g":"«Sobre la libertad», 1859","t":"Clásico sólido, fuente primaria"},{"w":"Edmund Burke","gen":"Fuente","n":"El cambio como reparación y no como demolición","g":"«Reflexiones sobre la Revolución en Francia», 1790","t":"Clásico sólido, fuente primaria"},{"w":"Benedict Anderson","gen":"Fuente","n":"La nación como comunidad imaginada","g":"«Comunidades imaginadas», 1983","t":"Clásico sólido, y discute con Gellner"},{"w":"Ernest Gellner","gen":"Fuente","n":"El nacionalismo atado a la industrialización","g":"«Naciones y nacionalismo», 1983","t":"Clásico sólido, y discute con Anderson"},{"w":"Colin Ward","gen":"Fuente","n":"El anarquismo completo, sin caricatura","g":"«Anarchism: A Very Short Introduction», 2004","t":"Entrada seria"},{"w":"Robert Paxton","gen":"Fuente","n":"El fascismo por lo que hace","g":"«Anatomía del fascismo», 2004","t":"Académico sólido"},{"w":"Roger Griffin","gen":"Fuente","n":"El fascismo por el mito del renacer nacional","g":"«The Nature of Fascism», 1991","t":"Académico sólido, definición en disputa"},{"w":"Umberto Eco","gen":"Fuente","n":"Los catorce rasgos que calzan demasiado fácil","g":"«Ur-Fascism», 1995","t":"Ensayo célebre: estatus de ensayo, no de ciencia"},{"w":"Cas Mudde","gen":"Fuente","n":"El populismo como ideología delgada","g":"«The Populist Zeitgeist», 2004","t":"Académico sólido"}];
const completeTaskDB=[{"s":"Cada familia entra por su mejor ___.","opts":["versión","cifra","época"],"ans":"versión"},{"s":"Mill puso la ___ en el núcleo, en 1859.","opts":["libertad","nación","igualdad"],"ans":"libertad"},{"s":"Burke desconfiaba de los planes ___.","opts":["perfectos","baratos","lentos"],"ans":"perfectos"},{"s":"Anderson llamó a la nación comunidad ___.","opts":["imaginada","fabricada","heredada"],"ans":"imaginada"},{"s":"Gellner la ató a la ___.","opts":["industrialización","religión","geografía"],"ans":"industrialización"},{"s":"El anarquismo rechaza la autoridad que no puede ___.","opts":["justificarse","crecer","pagar"],"ans":"justificarse"},{"s":"Paxton define el fascismo por lo que ___.","opts":["hace","dice","promete"],"ans":"hace"},{"s":"El populismo es una ideología ___.","opts":["delgada","gruesa","antigua"],"ans":"delgada"}];
const explainQuestions=[{"q":"¿Por qué en este arco la regla del acero es la regla madre, y qué señal indica que el núcleo que dibujaste de una familia está mal?","ans":"Porque esta etapa recorre el mapa político entero y cada familia entra por su mejor versión: la que sus propios militantes dirían en voz alta y con orgullo. Sin esa regla el recorrido se vuelve un desfile de ismos contados por sus enemigos, y contra una caricatura se gana todas las tardes sin haber tocado nunca al adversario real, lo que produce la ilusión de tener razón y ninguna capacidad de discutir con alguien que exista. La señal de que el dibujo salió mal es de un segundo y no es de opinión: si el núcleo que escribiste es un defecto, dibujaste un muñeco, porque nadie pone la codicia, el miedo, la envidia ni el odio en el centro de su propio ideario. Entonces la hoja se rehace, y la prueba definitiva es que alguien de esa familia lea la media página y no encuentre que le falta lo principal."},{"q":"Escribe el núcleo del liberalismo, del conservadurismo y del socialismo en su mejor versión, con su fuente y su etiqueta.","ans":"El liberalismo pone la libertad del individuo en el núcleo, y su mejor versión no es egoísta: nadie está en el lugar de otro adulto, así que nadie tiene autoridad para decidir por él lo que le conviene. Su fuente primaria es Mill, «Sobre la libertad» (1859), clásico sólido. El conservadurismo pone la desconfianza de los planes perfectos, y entiende el cambio como reparación y no como demolición, porque lo que funciona costó siglos y casi nadie sabe explicar por qué funciona. Su fuente primaria es Burke, «Reflexiones sobre la Revolución en Francia» (1790), clásico sólido, escrito mirando la Revolución cuando nadie sabía cómo iba a terminar. El socialismo pone la igualdad y la comunidad: nadie se salva solo y el punto de partida cuenta. El plano general está en Heywood, «Political Ideologies», manual académico sólido como manual, y su rasgo propio es un siglo de variantes internas que pelean entre sí más que con nadie."},{"q":"¿Por qué se dice que el nacionalismo es la familia que se cuela en todas las demás, y en qué se discuten Anderson y Gellner?","ans":"Porque casi nunca viene solo: se engancha a un liberalismo, a un conservadurismo o a un socialismo y les cambia una sola cosa, que es a quién se le debe algo. Por eso dos textos con el mismo núcleo declarado pueden dar decisiones contrarias según a quién incluyan en el «nosotros». Sus dos clásicos son de 1983 y se discuten entre sí. Anderson, en «Comunidades imaginadas», dice que la nación existe porque millones que nunca se van a conocer se piensan juntos, con el periódico y el libro impreso como motor, e insiste en que imaginada no quiere decir falsa. Gellner, en «Naciones y nacionalismo», dice que la nación se fabrica y que la fabrica la industrialización, porque necesita gente móvil, alfabetizada y con una sola lengua de escuela: es el nacionalismo el que engendra las naciones y no al revés. Anderson le objetó que confunde inventar con falsificar, cuando inventar también quiere decir imaginar y crear. Los dos son clásicos sólidos y la disputa se presenta con los dos lados nombrados."},{"q":"Explica el núcleo del anarquismo y por qué la caricatura de la bomba es el error más caro que se comete con esta familia.","ans":"Su núcleo es el rechazo de la autoridad que no puede justificarse, y toda la diferencia está en la letra pequeña: no dice «de toda autoridad», dice de la que no puede justificarse. La pregunta que hace no es «¿destruimos esto?», es «¿con qué derecho manda usted aquí?», y es una pregunta que cualquiera puede contestar si tiene con qué. La caricatura de la bomba es el error más caro por dos razones. La primera es de método: convierte a la familia en un muñeco, y contra un muñeco no se aprende nada ni se discute con nadie. La segunda es de hechos: la pregunta de esta familia ha producido muchas más cooperativas que atentados, y los atentados salen en el periódico precisamente porque son raros. Su entrada seria es Colin Ward, «Anarchism: A Very Short Introduction» (2004), etiquetada como entrada seria, y Ward insistía en algo comprobable: buena parte de lo que hace funcionar un barrio ya se organiza sin que nadie mande."},{"q":"¿Cuándo la palabra «fascista» describe y cuándo solo escupe? Nombra las cuatro piezas del debate definicional con su etiqueta.","ans":"Describe cuando viene con una definición que predice algo comprobable, y solo escupe cuando no viene con ninguna: entonces no dice nada del que la recibe y solo avisa a los presentes de a quién hay que morder. Las cuatro piezas del debate, con su etiqueta. Paxton, «Anatomía del fascismo» (2004), académico sólido: lo define por lo que hace y no por lo que dice, mirando las etapas y sobre todo las alianzas con las élites que le abren la puerta. Griffin, «The Nature of Fascism» (1991), académico sólido con definición en disputa: lo define por el mito del renacer nacional. Eco, «Ur-Fascism» (1995), ensayo célebre con estatus de ensayo y no de ciencia: catorce rasgos de los que basta que aparezca uno, y una lista que da positivo con casi todo no mide nada. Y Sternhell, «Ni derecha ni izquierda» (1983), tesis discutida: lo hace nacer de un cruce de nacionalismo y revisión del marxismo en la Francia de entreguerras, y el debate queda más honesto con ella dentro. La razón práctica de no gastar la palabra es sencilla: quien la usa con todo el mundo se queda sin ella el día que de verdad haga falta."},{"q":"¿Qué es una ideología delgada, y por qué esta etapa gira el detector hacia adentro con la regla de pago?","ans":"Una ideología delgada es la que tiene un núcleo tan escaso que no alcanza para decidir nada por sí solo. Mudde definió así el populismo en «The Populist Zeitgeist» (2004), académico sólido: el pueblo puro contra la élite corrupta, y nada más. De ahí se sigue lo que se ve en la práctica: necesita engancharse a una familia anfitriona, de izquierda o de derecha, y por eso dos movimientos populistas pueden pedir cosas contrarias sin dejar de ser lo mismo. La segunda fuente es Mudde con Cristóbal Rovira Kaltwasser (2017), académico sólido y escrito a medias desde América Latina. El giro hacia adentro es el cuidado central del arco: diseccionar el ideario del bando contrario lo hace cualquiera y no cuesta nada, y un detector que solo se prueba con los textos de los otros no es un instrumento, es un arma. La regla de pago lo vuelve procedimiento: un desenmascaramiento propio por cada uno ajeno, y el pago se hace con el ideario MÁS PARECIDO al propio, no con el más lejano, porque con el lejano se cumple la apariencia y no el propósito."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> La libertad del individuo, que no se sacrifica a ningún plan colectivo. → <span style="color:var(--jade);font-weight:700;">Núcleo del liberalismo (Mill, 1859)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

