function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"El borrador de la unidad de M.E.T.A.S sobre las familias políticas dice, en el renglón de una de ellas, que lo que esa gente quiere en el fondo es mandar. Se lee redondo y nadie lo objetó."},{"txt":"Una fundación extranjera ofrece L 90,000 para una unidad de «educación para la democracia», con material propio que reparte las siete familias en dos grupos: las compatibles con la democracia y las otras."},{"txt":"En la misma semana llaman comunista a M.E.T.A.S porque es gratuita, y fascista al autor porque exige orden en las tareas. Ninguna de las dos palabras viene con definición."},{"txt":"Un colegio del barrio ofrece L 25,000 por un taller para sus maestros, con una condición escrita: que no se hable de ideologías, solo de valores."},{"txt":"A Jael le toca la prueba dura: media página de la familia política que peor le cae, tan bien escrita que un militante la firmaría. El primer intento le puso como núcleo un defecto."},{"txt":"En el acto del quince de septiembre, Angelly pregunta por qué se le hace un nudo con un himno de gente que no conoce. No hay oferta ni lempiras: hay una niña con la pregunta que Anderson contestó en 1983."},{"txt":"Una página de memes ofrece L 15,000 por un material con la lista de catorce rasgos de Eco en tarjetas, aplicada a la política hondureña de este mes."},{"txt":"Dibujando el mapa completo, el autor llega al último dibujo, que es el de esta casa, y el núcleo de M.E.T.A.S sale más parecido al liberalismo de Mill que a lo que la familia dice de sí misma."}];
const critCaseQuestions=["1. ¿De qué familia es el texto o la acusación del caso, y cómo se sabe sin que se declare? Nombra la afirmación que se da por hecha y nunca se argumenta.","2. Escribe su núcleo en la versión que un militante de esa familia firmaría, y di qué señal delataría que lo que escribiste es un muñeco.","3. ¿Qué fuente sostiene esa descripción y qué etiqueta de estatus le toca? Si el caso toca el fascismo o el populismo, nombra las definiciones en disputa.","4. ¿Qué condición escrita deja la casa, y qué familia propia se parece a esta lo bastante para que haya que dibujarla también?"];
const critCaseGuides=["Se empieza por la familia, y no se busca por las palabras que el texto repite, porque pueblo, libertad, patria, justicia y orden las usan todas. Se busca al revés: la afirmación que el texto da por hecha y nunca defiende, como si defenderla fuera una grosería. Esa afirmación es el centro, y el centro es la familia. Después se mira si el nacionalismo viene colado, porque casi nunca viene solo y lo que cambia al engancharse es a quién se le debe algo; y si lo único que aparece es el pueblo puro contra la élite corrupta, entonces no hay casa sino puerta, y hay que buscar la familia anfitriona a la que se pegó.","El núcleo se escribe en la versión que un militante firmaría, y aquí es donde la regla del acero manda por ser la regla madre de este arco: el liberalismo dice que nadie está en el lugar de otro adulto, el conservadurismo que lo que funciona costó siglos y se remienda antes de demolerse, el socialismo que nadie se salva solo y que el punto de partida cuenta, el anarquismo que la autoridad que no puede justificarse no manda sino abusa. La señal de que lo escrito es un muñeco es de un segundo: si el núcleo es un defecto (codicia, miedo, envidia, odio), nadie de esa familia lo pondría en su propio centro, y la hoja se rehace. La prueba definitiva no es de opinión: se le da a leer a alguien de esa familia y se le pregunta si le falta lo principal.","Toda fuente pasa por la regla del estatus, y aquí las etiquetas están fijadas: Heywood, «Political Ideologies», manual académico sólido como manual; Mill, «Sobre la libertad» (1859), y Burke, «Reflexiones sobre la Revolución en Francia» (1790), clásicos sólidos y fuentes primarias; Anderson, «Comunidades imaginadas» (1983), y Gellner, «Naciones y nacionalismo» (1983), clásicos sólidos que se discuten entre sí, y se nombran los dos; Ward (2004), entrada seria. Si el caso toca el fascismo, entran sus cuatro piezas con su etiqueta: Paxton (2004), académico sólido, por lo que hace; Griffin (1991), académico sólido con definición en disputa, por el mito del renacer; Eco (1995), ensayo célebre y no ciencia, porque basta un rasgo de los catorce y así la lista da positivo con casi todo; y Sternhell (1983), tesis discutida. Si toca el populismo, Mudde (2004) y Mudde con Rovira Kaltwasser (2017), académicos sólidos. Los lempiras se dicen enteros, con lo que compran y con lo que piden a cambio.","Todo caso termina con la condición escrita y con el pago. La condición es concreta y se puede leer: qué se publica, qué se reescribe, qué queda declarado como crítica de la casa y aparte del núcleo ajeno, y con qué textos se entrena, que son históricos o de fuera, porque a ningún político vivo del país se le reparte etiqueta y en esta etapa el cuidado es doble, ya que «fascista» y «populista» son las dos palabras más gastadas del debate diario. Y el pago no es opcional: se dibuja también la familia propia, y se dibuja con la MÁS PARECIDA y no con la más lejana, porque dibujar a la que ya disgusta es el ejercicio cómodo y casi siempre sale un muñeco sin que nadie lo note. Si en el dibujo propio aparece algo que nunca se había declarado, se escribe, y se le pone su renglón de qué evidencia lo haría cambiar; si ese renglón no existe, funciona como dogma y así se anota, con fecha."];

const critErrorBank=[{"txt":"\"El núcleo de esa familia es la codicia, y con eso está dicho todo\".","g1":"Eso no es un núcleo, es un insulto ordenado. Nadie pone un defecto en el centro de su propio ideario, así que lo dibujado es un muñeco, y contra un muñeco se gana todas las tardes sin haber tocado nunca al adversario real.","g2":"La corrección la manda la regla del acero, que en este arco es la regla madre: se rehace la hoja con el núcleo que un militante firmaría, y la prueba es dársela a leer a alguien de esa familia y preguntarle si le falta lo principal."},{"txt":"\"Burke era un reaccionario con miedo al futuro: eso es el conservadurismo\".","g1":"La caricatura se cae con los hechos del propio Burke: defendió a los colonos americanos y pasó años persiguiendo los abusos de una compañía imperial en la India. Su desconfianza no era del cambio.","g2":"La corrección: el núcleo es la desconfianza de los planes perfectos, y el cambio como reparación y no como demolición. Escrito así, se le puede discutir en serio, y la discusión se vuelve mucho más difícil, que es exactamente lo que se busca."},{"txt":"\"Cito a Anderson y a Gellner juntos porque los dos explican el nacionalismo\".","g1":"Los dos son de 1983 y no se llevan bien: para Gellner la nación se fabrica y el nacionalismo trabaja con una máscara; para Anderson se imagina, y la imaginación es verdadera. Anderson le objetó justamente que confundía inventar con falsificar.","g2":"La corrección: se citan los dos y se dice que discuten. Presentar una disputa como acuerdo es mentir en silencio, y además quien elige un lado sin conocer el otro no eligió: heredó."},{"txt":"\"El anarquismo es la bomba: por eso no se estudia en serio\".","g1":"Su núcleo no es el rechazo de toda autoridad, sino de la que no puede justificarse, y esa letra pequeña es toda la familia. La caricatura impide ver la pregunta, que es «con qué derecho manda usted aquí».","g2":"La corrección: entra completo, con su entrada seria (Ward, 2004), y con el hecho comprobable que desarma el dibujo: esa pregunta ha producido muchas más cooperativas que atentados, y los atentados salen en el periódico porque son raros."},{"txt":"\"Le corrí la lista de catorce rasgos de Eco y dio positivo: caso cerrado\".","g1":"El propio Eco advierte que basta que uno de los catorce esté presente, así que la lista da positivo con un colegio, con una liga de fútbol y con la mayoría de las familias. Una lista que da positivo con casi todo no mide nada.","g2":"La corrección: la lista se queda donde le toca, como ensayo espléndido para pensar, y para medir se usan los instrumentos hechos para eso: Paxton, por lo que hace y con qué élites se alió, o Griffin, por el mito del renacer, que además sigue en disputa."},{"txt":"\"Ya dibujé las seis familias ajenas: la etapa está cumplida\".","g1":"Falta la que cuesta. Dibujar lo ajeno lo hace cualquiera y no cuesta nada; la etapa pide además la propia, y un detector que solo se prueba con los textos de los otros no es un instrumento, es un arma.","g2":"La corrección es la regla de pago corriendo de verdad: un desenmascaramiento propio por cada uno ajeno, y con el ideario MÁS PARECIDO al propio, porque con el más lejano se cumple la apariencia y no el propósito."}];

const critDecisionBank=["El borrador de la unidad dice que esa gente «en el fondo quiere mandar»: ¿se publica, se corrige o se rehace? ¿Y qué renglón se escribe en su lugar?","La fundación espera respuesta por los L 90,000: ¿se acepta el material, se acepta reescribiendo, o no se acepta? ¿Qué se reescribe exactamente?","Llegaron las dos palabras, «comunista» y «fascista», sin definición: ¿se contesta, se calla, o se hace otra cosa? ¿Qué exactamente?","El colegio pide un taller de L 25,000 sin hablar de ideologías: ¿se da el taller, y con qué textos se entrena para cumplir la condición sin traicionar el tema?","Jael tiene su media página con un defecto en el núcleo: ¿qué se hace con esa hoja, y cómo se sabe cuándo la nueva ya sirve?","Angelly pregunta por el nudo en la garganta con el himno: ¿qué se le contesta a su edad, y qué pregunta se le deja abierta después?","La página de memes espera por los L 15,000 y la lista de catorce rasgos: ¿se hace el material, se hace otro, o no se hace? ¿Con qué razones?","El núcleo propio salió más parecido al liberalismo de Mill que a lo que la casa dice de sí misma: ¿se escribe, se discute o se corrige? ¿Y qué renglón se le agrega?"];
const critDecisionGuide="La decisión correcta sigue siempre el mismo orden. Primero se nombra la familia, y no se busca por las palabras que el texto repite (pueblo, libertad, patria, justicia y orden las usan todas) sino por la afirmación que el texto da por hecha y nunca argumenta: esa afirmación es el centro, y el centro es la familia. Después se escribe su núcleo en la versión que un militante firmaría, porque en este arco la regla del acero es la regla madre, y hay una señal de un segundo para saber si salió mal: si el núcleo escrito es un defecto, nadie de esa familia lo pondría en su propio centro, así que se dibujó un muñeco y la hoja se rehace. Se mira además si el nacionalismo viene colado, porque casi nunca viene solo y lo que cambia es a quién se le debe algo; y si lo único que aparece es el pueblo puro contra la élite corrupta, se busca la familia anfitriona, porque eso es una ideología delgada y no una casa. Luego pasan las fuentes por la regla del estatus, con fecha y etiqueta: Heywood como manual académico sólido, Mill 1859 y Burke 1790 como clásicos sólidos y fuentes primarias, Anderson y Gellner (los dos de 1983) como clásicos sólidos que se discuten entre sí y por tanto los dos nombrados, Ward 2004 como entrada seria, Paxton 2004 como académico sólido, Griffin 1991 como académico sólido con definición en disputa, Eco 1995 con estatus de ensayo y no de ciencia, Sternhell 1983 como tesis discutida, y Mudde 2004 y 2017 como académico sólido; y los lempiras se dicen enteros, con lo que compran y con lo que piden a cambio. Y al final se escribe la condición y se paga la regla: el entrenamiento va con textos históricos o de fuera y a ningún político vivo del país se le reparte etiqueta, con cuidado doble porque fascista y populista son las dos palabras más gastadas del debate diario; y se dibuja también la familia propia, con la MÁS PARECIDA y no con la más lejana, porque un detector que solo se prueba con los textos de los otros no es un instrumento, es un arma.";

const critCompareBank=[{"a":"Publicar la unidad con el núcleo de cada familia en la versión que un militante firmaría, y la crítica de la casa aparte.","b":"Publicar la unidad con el núcleo que aplaude la mitad del barrio.","ga":"Caso A: el niño sale sabiendo reconocer un texto real, y la crítica de la casa vale porque cae en el cuerpo y no en el aire.","gb":"Caso B: se gana un aplauso inmediato y se pierde la mitad de las casas, y además el niño queda entrenado contra adversarios que no existen.","gr":"Poner en pie a alguien no es darle la razón: es asegurarse de que el golpe caiga en el cuerpo real, y eso es lo único que vuelve útil la crítica."},{"a":"Decir «fascista» nombrando la definición y lo que predice.","b":"Decir «fascista» sin definición, porque el otro cae mal.","ga":"Caso A: la palabra describe, se puede ir a comprobar si es verdad, y quien la recibe puede defenderse o quedar retratado con hechos.","gb":"Caso B: la palabra no dice nada del otro y solo avisa a los presentes de a quién morder, y de paso pierde el filo para siempre.","gr":"La palabra que se le pone a todo el mundo deja de servir el día en que de verdad haga falta: gastarla es desarmarse."},{"a":"Estudiar el fascismo con el debate definicional entero: Paxton, Griffin, Eco con su estatus de ensayo y Sternhell como tesis discutida.","b":"Estudiarlo con la lista de catorce rasgos, que es corta y se entiende rápido.","ga":"Caso A: se aprende que hay una disputa real entre historiadores serios, y se sale con dos instrumentos que predicen algo comprobable.","gb":"Caso B: se sale con un termómetro que marca fiebre en un colegio, en una liga de fútbol y en la propia casa, es decir sin termómetro.","gr":"Una lista que da positivo con casi todo no mide nada, y un ensayo brillante sigue siendo un ensayo: el estatus de la fuente decide para qué sirve."},{"a":"Pagar la regla dibujando la familia propia, que resultó parecerse al liberalismo de Mill.","b":"Pagar la regla dibujando la familia política que peor le cae a la casa.","ga":"Caso A: el pago cuesta y por eso sirve: es donde aparecen las premisas propias sin declarar, porque el parecido obliga a mirar de cerca.","gb":"Caso B: se siente como pago y no lo es: dibujar a la que ya disgusta es el ejercicio cómodo, y suele salir un muñeco sin que nadie lo note.","gr":"La regla de pago se cumple con el ideario más parecido, no con el más lejano; con el lejano se cumple la apariencia."}];

const critCauseBank=[{"cause":"Se escribe el núcleo de una familia con un defecto en el centro.","guide":"Sale un muñeco: la crítica gana todas las tardes sin tocar al adversario real, los militantes de esa familia se confirman al verse mal leídos, y el alumno queda entrenado contra alguien que no existe."},{"cause":"Cada familia entra por su mejor versión antes de tocarla.","guide":"La crítica se vuelve más difícil y mucho más seria, y pasa algo medible: dos o tres objeciones viejas se caen solas porque atacaban cosas que esa familia no sostiene. Quedan menos objeciones, y las que quedan pesan."},{"cause":"Se cita a Anderson y a Gellner como si estuvieran de acuerdo.","guide":"La disputa desaparece del papel y el lector hereda un lado sin saber que había otro; y como la objeción de Anderson es precisamente sobre el punto central, lo que queda es una explicación mocha presentada como consenso."},{"cause":"Se usa «fascista» sin decir con qué definición.","guide":"La palabra deja de describir y solo avisa a quién morder, se gasta para todo el mundo, y el día en que hace falta para lo que Paxton describe ya no queda con qué decirlo."},{"cause":"El nacionalismo se estudia como una familia más, y no como la que se cuela.","guide":"Se pierde la explicación de por qué dos textos con el mismo núcleo declarado dan decisiones contrarias: la diferencia está en a quién incluye el «nosotros», y esa pieza es la que el nacionalismo cambia al engancharse."},{"cause":"La casa dibuja su propia familia con el mismo mapa, y con la más parecida.","guide":"Aparecen las premisas que nunca se declararon y de las que sin embargo salían decisiones; cada una queda escrita con su renglón de qué evidencia la haría cambiar, y el instrumento se vuelve usable fuera de esta mesa."}];
const critEffectBank=[{"effect":"La unidad se publicó con los siete núcleos escritos en su mejor versión.","guide":"El renglón del defecto se rehizo: ninguna familia quedó con la codicia, el miedo, la envidia o el odio en el centro, y la crítica de la casa quedó aparte, con su nombre y en la misma página, para que se viera cuál era cuál."},{"effect":"El material de la fundación entró reescrito, y el debate del fascismo con sus cuatro piezas.","guide":"Las familias que el material caricaturizaba se reescribieron; el fascismo entró con Paxton, Griffin, Eco con su estatus de ensayo y Sternhell como tesis discutida; el financiador apareció con su nombre en lo que financió y el control editorial quedó entero en la casa."},{"effect":"A las dos palabras sin definición no se les contestó con otra etiqueta.","guide":"Se contestó con lo que la casa hace y con quién la paga, y se explicó la prueba de los cinco segundos: con qué definición, y qué predice. La razón no fue moral sino práctica: la palabra que se le pone a todo el mundo se queda sin filo."},{"effect":"El taller del colegio se dio, y nadie salió con una etiqueta puesta.","guide":"Se entrenó con textos históricos o de fuera, ninguna familia se nombró por su caricatura y ninguna etiqueta cayó sobre nadie vivo del país. El colegio tuvo la paz que quería, y los maestros salieron con el mapa completo."},{"effect":"La media página de Jael quedó firmada por alguien de esa familia.","guide":"El primer intento tenía un defecto en el núcleo y se rehizo. Al terminar, dos de sus objeciones viejas se cayeron solas porque atacaban cosas que esa familia no sostiene, y la que quedó pesaba el doble."},{"effect":"El parecido de la casa con el liberalismo de Mill quedó escrito en el inventario de gafas.","guide":"Con su renglón de qué evidencia lo haría cambiar: un cotejo de resultados que muestre que el estudio decidido en familia rinde menos que el decidido por cada uno. Sin ese renglón habría quedado anotado como dogma, con fecha."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧬 La familia en la mesa · Forma ${cf} · El mapa de las familias · Ruta de las Gafas a la Vista`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La familia en la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿De qué familia es el texto del caso y cómo se sabe sin que se declare, y cuál es su núcleo en la versión que un militante firmaría? Explica qué fuente lo sostiene con su etiqueta de estatus, la condición escrita que deja la casa y qué familia propia hay que dibujar para pagar la regla.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos pone en pie la mejor versión y cuál dibuja un muñeco? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La familia en la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La familia en la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿De qué familia es el texto del caso y cómo se sabe sin que se declare, y cuál es su núcleo en la versión que un militante firmaría? Explica qué fuente lo sostiene con su etiqueta de estatus, la condición escrita que deja la casa y qué familia propia hay que dibujar para pagar la regla.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos pone en pie la mejor versión y cuál dibuja un muñeco? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La familia en la mesa El mapa de las familias · Ruta de las Gafas a la Vista · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #78350f;background:#fdf3e7;color:#78350f;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#78350f;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #78350f;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#fdf3e7;border-left:3px solid #78350f;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#fdf3e7;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#fdf3e7;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#78350f;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #78350f;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La familia en la mesa · El mapa de las familias · Ruta de las Gafas a la Vista · Etapa 3 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La familia en la mesa · El mapa de las familias · Ruta de las Gafas a la Vista · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

