const timelineData=[{"y":"1790","icon":"🏛️","label":"Burke mira la Revolución","text":"<strong>Edmund Burke</strong> publica las <strong>«Reflexiones sobre la Revolución en Francia»</strong> cuando nadie sabía cómo iba a terminar: el núcleo del conservadurismo es la <strong>desconfianza de los planes perfectos</strong>, y el cambio como <strong>reparación y no como demolición</strong>. Etiqueta: <strong>clásico sólido, fuente primaria</strong>."},{"y":"1859","icon":"🕊️","label":"Mill pone la libertad en el centro","text":"En <strong>«Sobre la libertad»</strong>, <strong>John Stuart Mill</strong> da el argumento que no es egoísta: <strong>nadie está en el lugar de otro adulto</strong>, así que nadie tiene autoridad para decidir por él lo que le conviene. Etiqueta: <strong>clásico sólido, fuente primaria</strong>."},{"y":"Un siglo","icon":"🤝","label":"El socialismo y su pleito interno","text":"Núcleo: <strong>la igualdad y la comunidad</strong>, porque nadie se salva solo y el punto de partida cuenta. Y su rasgo propio: <strong>un siglo de variantes internas que pelean entre sí más que con nadie</strong>. Quien no lo sabe confunde a un socialdemócrata con un leninista y no entiende a ninguno."},{"y":"1983","icon":"🏴","label":"Anderson y Gellner, dos libros y un pleito","text":"<strong>Anderson</strong> («Comunidades imaginadas»): la nación existe porque <strong>millones que nunca se conocerán se piensan juntos</strong>. <strong>Gellner</strong> («Naciones y nacionalismo»): la nación <strong>se fabrica</strong>, y la fabrica la industrialización. <strong>Clásicos sólidos que se discuten entre sí</strong>, y los dos se nombran."},{"y":"2004","icon":"🕊️","label":"El anarquismo, completo","text":"<strong>Colin Ward</strong>, «Anarchism: A Very Short Introduction»: <strong>entrada seria</strong>. Núcleo: el <strong>rechazo de la autoridad que no puede justificarse</strong>, y no de toda autoridad. Su pregunta <strong>ha producido más cooperativas que atentados</strong>, y la caricatura con bomba se queda fuera."},{"y":"El debate","icon":"⚖️","label":"El fascismo, en disputa","text":"<strong>Paxton (2004)</strong>, académico sólido: por lo que <strong>hace</strong>, sus etapas y las <strong>alianzas con las élites</strong>. <strong>Griffin (1991)</strong>, académico sólido con <strong>definición en disputa</strong>: el <strong>mito del renacer nacional</strong>. <strong>Eco (1995)</strong>: <strong>ensayo, no ciencia</strong>, catorce rasgos que calzan demasiado fácil. <strong>Sternhell (1983)</strong>: <strong>tesis discutida</strong>, y el debate queda más honesto con ella dentro."},{"y":"2004 y 2017","icon":"🪶","label":"Mudde y la ideología delgada","text":"<strong>«The Populist Zeitgeist» (2004)</strong>: el populismo es <strong>el pueblo puro contra la élite corrupta</strong> y nada más, un núcleo tan flaco que <strong>necesita familia anfitriona</strong>, de izquierda o de derecha. Con <strong>Rovira Kaltwasser (2017)</strong>, la introducción breve <strong>escrita a medias desde América Latina</strong>. Etiqueta: <strong>académico sólido</strong>."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

