let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(acero){sfx(acero?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(acero){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>El núcleo quedó reescrito en su mejor versión:</strong> la frase que un militante de esa familia diría en voz alta y con orgullo, y la crítica de la casa aparte, con su nombre, en la misma página para que se vea cuál es cuál.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⚖️</span><span class="ms-text"><strong>Y entonces pasó lo que tenía que pasar:</strong> la crítica se volvió más difícil y mucho más seria, y dos objeciones viejas se cayeron solas porque atacaban cosas que esa familia no sostiene. Poner en pie no es dar la razón: es que el golpe caiga en el cuerpo real.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🎭</span><span class="ms-text"><strong>Quedó publicado un muñeco:</strong> un defecto en el centro de un ideario ajeno, que nadie de esa familia firmaría. Se lee redondo, aplaude la mitad del barrio y no describe a nadie que exista.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega en dos partes:</strong> se pierden las casas donde esa familia se vota, y el niño queda entrenado para ganarle todas las tardes a un adversario que no existe. La hoja se rehace en su mejor versión.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

