const lectComprensionBank=[{"t":"Borges","q":"¿Qué tarea le encomendó el director al narrador con el segundo cajón?","o":["a) Repartir por familia ciento cuarenta folletos sin portada ni firma","b) Encuadernar los libros dañados por la humedad","c) Redactar el catálogo de los libros firmados","d) Devolverle el cajón a la viuda"],"c":0},{"t":"Borges","q":"¿Por qué fracasó en tres días el método de buscar palabras?","o":["a) Porque los folletos estaban en otro idioma","b) Porque todos los folletos usaban las mismas palabras","c) Porque no sabía leer letra de máquina","d) Porque el director le quitó el trabajo"],"c":1},{"t":"Borges","q":"¿En qué consiste el método que el narrador descubre?","o":["a) Buscar la palabra que más se repite","b) Contar las páginas de cada folleto","c) Buscar la afirmación que el folleto nunca argumenta","d) Preguntarle a la viuda por su marido"],"c":2},{"t":"Borges","q":"¿Qué hizo el narrador después de que la lista de catorce rasgos de Eco diera positivo con el folleto?","o":["a) Cerró el caso y archivó el folleto","b) Le escribió a Eco para preguntarle","c) Repitió la lista tres veces más con el mismo folleto","d) La aplicó al boletín parroquial, al reglamento del colegio y a un discurso, y dio positivo con los tres"],"c":3},{"t":"Borges","q":"¿Qué descubre el narrador sobre el último folleto del cajón?","o":["a) Que era suyo, escrito a los veintitrés años","b) Que era del marido de la viuda","c) Que estaba en blanco","d) Que lo había escrito el director de la biblioteca"],"c":0},{"t":"Cervantes","q":"¿Qué ordenó don Quijote que hiciera cada uno de los siete caminantes?","o":["a) Que se callaran hasta que dejara de llover","b) Que dijera lo que de veras quiere, y que después lo repitiera el que peor le cae","c) Que escribieran el nombre de su enemigo","d) Que pagaran al ventero por el ruido"],"c":1},{"t":"Cervantes","q":"Según don Quijote, ¿qué pinta el que pinta al vecino con los colores que al vecino no le gustan?","o":["a) Un retrato exacto","b) Un mapa de la comarca","c) Un espantajo, contra el que se vence todas las tardes sin quebrar lanza","d) Una carta de queja"],"c":2},{"t":"Cervantes","q":"¿Con qué imagen explica don Quijote a los dos que solo decían que el pueblo es limpio y los mandones sucios?","o":["a) Que traen un pozo sin agua","b) Que traen una lanza sin punta","c) Que traen un caballo sin silla","d) Que traen solamente una puerta, y una puerta sin casa se cuelga de la pared del vecino"],"c":3},{"t":"Cervantes","q":"¿Cómo distingue don Quijote el nombre que describe del nombre que solo escupe?","o":["a) El que describe dice qué hace aquel a quien se pone, y se puede ir a mirar si es verdad","b) El que describe es más corto","c) El que describe lo dice un caballero y el otro un escudero","d) El que describe se dice en voz baja"],"c":0},{"t":"Cervantes","q":"¿Qué le quiso comprar Sancho al de los mandones sucios?","o":["a) El cántaro de vino","b) La puerta, si se la daban sin casa, para ponérsela a su choza","c) Un melón de la venta","d) La bandera de su aldea"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿qué hacen las siete familias de ideas, entendidas como sistemas operativos?","o":["a) Dicen exactamente qué pensar de cada cosa","b) Sustituyen a los gobiernos","c) Dicen qué preguntas hacer y a quién se le debe algo","d) Reparten el mundo en dos bandos"],"c":2},{"t":"Harari","q":"¿Con qué dos textos ilustra el ensayo el pleito interno del socialismo?","o":["a) Mill (1859) y Burke (1790)","b) Anderson (1983) y Gellner (1983)","c) Paxton (2004) y Griffin (1991)","d) El Manifiesto comunista de 1848 y el programa de Bad Godesberg de 1959"],"c":3},{"t":"Harari","q":"¿Qué dato da el ensayo sobre los miembros de las Naciones Unidas?","o":["a) Que en 1945 eran 51 y hoy son 193","b) Que en 1945 eran 100 y hoy son 200","c) Que siempre han sido los mismos","d) Que en 1983 llegaron a 51"],"c":0},{"t":"Harari","q":"¿Qué dos hechos usa el ensayo para darle la razón a Paxton?","o":["a) Dos elecciones perdidas por los fascismos","b) Que el rey Víctor Manuel III encargó gobierno a Mussolini en 1922 y que Hindenburg nombró canciller a Hitler el 30 de enero de 1933","c) Dos golpes de Estado por asalto","d) Dos listas de catorce rasgos"],"c":1},{"t":"Harari","q":"¿Cuál es la pregunta de cinco segundos que el ensayo propone para las palabras «fascista» y «populista»?","o":["a) Quién lo dijo primero","b) En qué periódico salió","c) Con qué definición, y qué predice","d) Si es de izquierda o de derecha"],"c":2},{"t":"Entrevista","q":"¿Qué dos lecturas le pide Bobbio a un joven antes de su primera pancarta, y para qué?","o":["a) El «Manifiesto comunista» y el programa de Bad Godesberg, para elegir bando","b) «Sobre la libertad» de Mill (1859) y las «Reflexiones» de Burke (1790), leídas para averiguar qué defiende cada una y no para refutarlas","c) «Derecha e izquierda» y «El futuro de la democracia», los dos suyos","d) Los libros de Anderson y Gellner, para entender la nación"],"c":1},{"t":"Entrevista","q":"Según «Derecha e izquierda» (1994), ¿qué separa en el fondo a la izquierda de la derecha?","o":["a) La honradez de sus dirigentes","b) La edad de sus votantes","c) El amor a la patria","d) La actitud ante la igualdad: un criterio que no reparte virtud, sino la carga de la prueba"],"c":3},{"t":"Entrevista","q":"¿Por qué dice Bobbio que los casos de 1922 y de 1933 incomodan a todo el mundo?","o":["a) Porque no fueron asaltos sino nombramientos: un rey y un presidente les abrieron la puerta","b) Porque ocurrieron el mismo año","c) Porque nadie los ha estudiado","d) Porque fueron golpes militares clásicos"],"c":0},{"t":"Entrevista","q":"¿Qué hizo Bobbio cuando en 1992 se publicó su carta de 1935 a Mussolini?","o":["a) La negó y denunció al semanario","b) Dijo que era una falsificación de sus adversarios","c) No la negó: reconoció que era suya, escrita con miedo, y que callarla habría sido una segunda carta peor","d) Guardó silencio hasta su muerte"],"c":2},{"t":"Entrevista","q":"¿Cuáles son las tres cosas que Bobbio le desea a la familia que enseña el mapa?","o":["a) Disciplina, memoria y obediencia","b) Aprender los núcleos antes que los insultos, escribir la media página que un militante firmaría, y no tenerle miedo a la duda","c) Leer solo a los clásicos de la propia familia","d) Evitar la política hasta la mayoría de edad"],"c":1},{"t":"Quintero y Gala","q":"¿Con qué imagen presenta Gala a las siete familias de ideas?","o":["a) Siete espadas de un mismo taller","b) Siete campanas de una misma torre","c) Siete barcos de un mismo puerto","d) Siete macetas de un mismo patio, cada una convencida de que el sol sale para ella"],"c":3},{"t":"Quintero y Gala","q":"¿Cómo distingue Gala el nombre que describe del que solo escupe?","o":["a) El que describe es un farol: dice qué hace el señalado y se puede ir a mirar; la piedra solo avisa a la cuadrilla de a quién morder","b) El que describe es más largo y culto","c) El que describe lo usan los poetas y el otro los políticos","d) No hay manera de distinguirlos"],"c":0},{"t":"Quintero y Gala","q":"¿Qué imagen usa Gala para los nombramientos de 1922 y de 1933 que le trae Quintero?","o":["a) Que rompieron la puerta a hachazos","b) Que entraron con llave, y la llave se la dieron los dueños de la casa","c) Que saltaron la tapia de noche","d) Que la casa estaba vacía"],"c":1},{"t":"Quintero y Gala","q":"¿Qué es una ideología delgada, en la imagen de Gala?","o":["a) Una vela que no alumbra","b) Un pozo sin agua","c) Un perchero: no abriga, pero sostiene cualquier abrigo","d) Una carta sin firma"],"c":2},{"t":"Quintero y Gala","q":"¿Con qué aforismo cierra Gala la conversación?","o":["a) El que mucho abarca poco aprieta","b) Las ideas se heredan como los patios","c) Nadie riega la maceta del vecino","d) Quien no sabe decir qué quiere su adversario, todavía no sabe qué quiere él"],"c":3}];
const lectCompletarBank=[{"t":"las tres","q":"Mill publicó «Sobre la libertad» en el año ___.","a":"1859"},{"t":"las tres","q":"Burke publicó sus «Reflexiones sobre la Revolución en Francia» en ___.","a":"1790"},{"t":"Borges","q":"En el segundo cajón venían ___ folletos sin portada ni firma.","a":"ciento cuarenta"},{"t":"Borges","q":"Mill dedicó su libro a la memoria de su esposa, Harriet ___.","a":"Taylor"},{"t":"Cervantes","q":"Don Quijote mandó que cada parecer fuese defendido por su ___.","a":"contrario"},{"t":"Cervantes","q":"Sancho recuerda que por rebuznar de gracia le molieron las costillas a ___.","a":"estacazos"},{"t":"Cervantes","q":"Al final quedaron cinco hojas firmadas y ___ sin firmar.","a":"dos"},{"t":"Harari","q":"La Alianza Cooperativa Internacional contabiliza alrededor de ___ millones de cooperativas en el mundo.","a":"tres"},{"t":"Harari","q":"Umberto Eco publicó «Ur-Fascism» en el año ___.","a":"1995"},{"t":"Harari","q":"El People's Party de los Estados Unidos se fundó en ___.","a":"1892"}];
const lectAnalisisBank=[{"q":"1. Las tres primeras lecturas llegan al mismo mapa por tres puertas. Explica qué hace cada voz que las otras dos no pueden hacer, y qué se perdería leyendo solo una.","guia":"El cuento instala un método y lo instala como experiencia: alguien tiene que clasificar sin firmas, fracasa con el método obvio, descubre que hay que buscar la afirmación que nunca se argumenta, y al final se encuentra a sí mismo dentro del cajón; eso se recuerda porque incomoda. El capítulo lo vuelve escena, pleito y refrán, y añade lo que los otros dos no tienen: el procedimiento hecho cuerpo, porque cada parecer se dice en voz alta y lo repite el que peor le cae, con hojas que no valen hasta que el otro dice que las firmaría. El ensayo lo pone a escala de especie y con datos comprobables, y por eso es el único que sirve para citar en una discusión: 51 miembros de la ONU en 1945 y 193 hoy, los tres millones de cooperativas, los nombramientos de 1922 y de 1933. Quien lee solo una se queda sin el método, sin el procedimiento o sin la prueba."},{"q":"2. El bibliotecario del cuento y don Quijote llegan a la misma regla por caminos distintos. Formula esa regla en una frase y explica cómo la alcanza cada uno.","guia":"La regla es la del acero, que en este arco es la regla madre: una familia solo se puede juzgar después de ponerla en pie en su mejor versión, es decir con el núcleo que sus propios militantes firmarían. El bibliotecario llega por el lado del conocimiento: necesita clasificar y descubre que la caricatura no clasifica, porque el folleto del anarquista proponía una cooperativa de panaderos y no un incendio, así que el dibujo que él traía en la cabeza no le servía para trabajar. Don Quijote llega por el lado del combate: dice que quien pinta al vecino con los colores que al vecino no le gustan no ha pintado a nadie, sino un espantajo, y que contra un espantajo se vence todas las tardes sin quebrar lanza. Uno la necesita para entender y el otro para pelear, y eso es lo interesante: la misma regla sirve al que quiere saber y al que quiere ganar, y por eso no depende de la buena voluntad de nadie."},{"q":"3. El cuento dice que «el nacionalismo no era un estante, era una humedad que había pasado por todos los estantes». Traduce la imagen al vocabulario de la etapa y da un ejemplo.","guia":"Traducida: el nacionalismo casi nunca funciona como familia autónoma, sino como pieza que se engancha a otras familias y les cambia una sola cosa, que es a quién se le debe algo, es decir a quién incluye el «nosotros». Por eso los folletos nacionalistas del cajón no formaban una sola pila: unos suponían el individuo y otros suponían la comunidad, y esos supuestos son núcleos de familias distintas. El ejemplo puede ser cualquiera que tenga las dos piezas, la familia anfitriona y la frontera del nosotros: un programa que defiende la libertad de emprender pero solo para los nacidos aquí, o un programa que defiende el reparto de la tierra pero solo entre los del pueblo. Las dos frases se leen distinto según a quién dejan fuera, y ninguna de las dos se entiende si no se ve la humedad. La consecuencia práctica es que hay que hacer dos preguntas y no una: qué familia es, y a quién incluye."},{"q":"4. ¿Por qué el bibliotecario le aplica la lista de Eco al boletín parroquial y al reglamento del colegio? Explica qué demuestra ese experimento y qué se salva de Eco.","guia":"Se la aplica por sospecha de sí mismo, y ese es el punto: acaba de obtener el resultado que quería y decide probar el instrumento donde no debería sonar. Suena igual. El experimento demuestra que la lista no discrimina, y la razón la da el propio Eco al advertir que basta que uno de los catorce rasgos esté presente: con ese umbral, casi cualquier institución humana da positivo, y un instrumento que da positivo con casi todo no informa de nada, aunque cada uno de sus catorce puntos sea agudo por separado. Lo que se salva de Eco es exactamente lo que es: un ensayo espléndido para pensar la familia, con observaciones que ayudan a mirar. Lo que no se salva es su uso como termómetro o como prueba en una acusación. Y de ahí la conducta correcta del cuento: guardar la lista y usar los instrumentos hechos para medir, Paxton por lo que hace y con qué élites se alió, o Griffin por el mito del renacer, con su definición en disputa declarada."},{"q":"5. En el capítulo, cinco caminantes «traen casa» y dos «traen solamente una puerta». Explica la distinción con el vocabulario de Mudde y di por qué don Quijote advierte que la puerta a veces manda más que la casa.","guia":"La casa es una ideología con núcleo suficiente para decidir cosas concretas: liberalismo, conservadurismo, socialismo, nacionalismo y anarquismo dicen algo sobre el trigo y sobre el pozo. La puerta es una ideología delgada, como Mudde definió el populismo en 2004: el pueblo puro contra la élite corrupta y nada más, un núcleo tan escaso que no alcanza para gobernar y por eso necesita engancharse a una familia anfitriona, de izquierda o de derecha. El capítulo lo demuestra con el interrogatorio: preguntados si son de moler trigo o de venderlo, y si el pozo ha de ser del concejo o del dueño, los dos de la puerta no saben. La advertencia de que la puerta manda más que la casa es la parte fina y evita leer «delgada» como «inofensiva»: quien controla quién entra y quién queda fuera del pueblo puro decide antes que cualquier programa, porque decide con quién se discute. Delgada describe el contenido del núcleo, no su fuerza."},{"q":"6. El ensayo afirma que en ochenta años «la especie no creció: se dividió en más nosotros». Defiende esa lectura con el dato de la ONU y explica qué le añade Gellner y qué le añade Anderson.","guia":"La lectura se defiende con la cifra: las Naciones Unidas se fundaron en 1945 con 51 miembros y hoy tienen 193, así que el número de unidades políticas que se reclaman nación se multiplicó casi por cuatro en ochenta años, sin que apareciera ningún continente nuevo. Es decir que lo que cambió no fue el mundo sino el trazado de los «nosotros». Gellner le añade el mecanismo y lo pone del lado de la función: una economía industrial necesita gente móvil, alfabetizada y con una sola lengua de escuela, así que la nación se fabrica, y es el nacionalismo el que engendra las naciones y no al revés. Anderson le añade el material y lo pone del lado de la imaginación: millones de personas que nunca se van a conocer se piensan juntas, con el periódico y el libro impreso como motor, e insiste en que imaginada no quiere decir falsa; de hecho le objetó a Gellner que confundía inventar con falsificar. Las dos mitades hacen falta: Gellner explica por qué apareció el molde y Anderson por qué la gente cabe adentro y llora con el himno."},{"q":"7. El capítulo dice que los nombres graves «en gastándolos se quedan sin filo». Explica la advertencia con el ancla real del rebuzno y con la razón práctica de esta etapa.","guia":"La advertencia es que una palabra usada para todo deja de significar algo, y por tanto deja de servir cuando de verdad hace falta. El ancla real está declarada en la tarjeta y viene del propio Quijote: en el cuento del rebuzno, dos aldeas llegan a las armas con banderas y pendones por el apodo de «rebuznadores», y Sancho, por rebuznar para demostrar su habilidad, recibe una paliza a estacazos. Un apodo de burlas basta para juntar ejércitos, y no porque describa nada, sino porque marca a quién hay que morder. La razón práctica de esta etapa es la misma y no es moral: «fascista» y «populista» son las dos palabras más gastadas del debate diario, y quien le dice fascista al que le exige puntualidad se queda sin palabra el día en que aparezca lo que Paxton describe. La conducta correcta es de una línea: se dice con qué definición y qué predice, o no se dice; y no se le pone a nadie vivo del país, porque el entrenamiento va con textos históricos o de fuera."},{"q":"8. El bibliotecario dice que no cambió de estante su propio folleto y que esa es la única virtud que se atribuye. ¿Por qué es ese gesto el centro del cuento, y cómo se relaciona con la regla de pago de la casa?","guia":"Porque es el único momento en que el instrumento se vuelve contra su dueño y no lo pierde. Un detector se puede usar de dos maneras que se ven iguales por fuera: como instrumento, si funciona igual en las dos direcciones, y como arma, si solo suena hacia afuera. El bibliotecario había clasificado ciento treinta y nueve folletos ajenos sin costo alguno, y el ciento cuarenta le costó su propia imagen de veinte años; dejarlo en su sitio es lo que valida todo lo anterior, porque prueba que el método no estaba calibrado para darle la razón. La regla de pago de la casa es esa misma exigencia convertida en procedimiento: un desenmascaramiento propio por cada uno ajeno, y con un detalle que la hace difícil, que el pago se hace con el ideario más parecido al propio y no con el más lejano, porque con el lejano se cumple la apariencia y no el propósito. Don Quijote lo dice con las mismas palabras en el camino: escribe una hoja tuya por cada hoja ajena, y del que más se te parece."},{"q":"9. El ensayo llama a las familias «sistemas operativos» y el cuento las llama «estantes». Compara las dos metáforas: qué acierta cada una y dónde falla.","guia":"La metáfora del sistema operativo acierta en la función: dice que una familia no da opiniones sueltas sino que fija qué preguntas se hacen y a quién se le debe algo, es decir que trabaja por debajo de las posiciones concretas, y eso explica por qué dos personas con el mismo dato deciden distinto. Falla en que sugiere un programa cerrado y estable, cuando el socialismo tiene un siglo de variantes internas que pelean entre sí y el fascismo no tiene ni definición acordada. La metáfora del estante acierta en lo contrario: es la del que tiene que decidir dónde va cada texto real, con las manos, y de ahí sale el hallazgo del cuento, que el nacionalismo no es un estante sino una humedad, y que once folletos no encuentran estante porque son demasiado flacos para andar solos. Falla en que un estante es exterior al libro y da a entender que la familia es una etiqueta que se pone desde fuera. Juntas dicen la verdad: por dentro funciona como sistema, y por fuera hay que clasificarla a mano y aceptar que algunas casillas no cierran."},{"q":"10. Los cinco textos llevan la etiqueta de ejercicio de estilo de la casa. Explica por qué esa etiqueta pertenece al temario de esta etapa en particular, y qué pasaría si se quitara.","guia":"Porque esta etapa enseña a reconocer una familia en un texto que no se declara, y un pastiche sin declarar es exactamente un texto que no se declara, pero en el peor de los sentidos: no esconde su familia, esconde su autoría, y con ella la autoridad que el lector le concede. Enseñar a exigir la firma y no firmar sería la contradicción más rápida posible. Hay además una razón propia de esta etapa: la voz es una manera de ganar sin argumentos, porque una tesis suena más verdadera dicha con la prosa de Borges o con el periodo de Cervantes, y la etiqueta obliga al lector a separar lo que convence por razón de lo que convence por timbre, que es la misma separación que hay entre un núcleo dibujado y un muñeco bien escrito. Si se quitara, pasarían dos cosas comprobables: alguien citaría a Anderson, a Paxton o a Mudde a través de una frase que ninguno escribió, y la casa quedaría produciendo el tipo de fuente inflada que su propio compendio manda cazar."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

/* ---------- III. Análisis complejo ---------- */
let laIdx=0,laPautaVisible=false;
function showLectA(){const cont=document.getElementById('laQ');if(!cont)return;const d=lectAnalisisBank[laIdx];document.getElementById('laProg').textContent='Pregunta '+(laIdx+1)+' de '+lectAnalisisBank.length;cont.textContent=d.q;const p=document.getElementById('laPauta');p.innerHTML='<strong>Pauta:</strong> '+d.guia;p.style.display=laPautaVisible?'block':'none';document.getElementById('laTA').value='';}
function nextLectA(){sfx('click');laIdx=(laIdx+1)%lectAnalisisBank.length;showLectA();}
function prevLectA(){sfx('click');laIdx=(laIdx-1+lectAnalisisBank.length)%lectAnalisisBank.length;showLectA();}
function toggleLectAPauta(){sfx('click');laPautaVisible=!laPautaVisible;const p=document.getElementById('laPauta');p.style.display=laPautaVisible?'block':'none';const b=document.getElementById('btnLectAPauta');if(b)b.textContent=laPautaVisible?'🙈 Ocultar pauta':'👁 Ver pauta';}

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso: una hoja
// suelta con un pastiche sin declarar es exactamente la fuente inflada que
// el Estudio Mayor enseña a cazar.
const LECTURAS_IMPR={
  borges:{titulo:'El cajón de los siete sin firma',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'De cómo cada parecer fue defendido por su contrario',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'Siete sistemas operativos para una sola especie',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  // Las entrevistas llevan etiqueta propia: además del pastiche hay que
  // declarar que el encuentro nunca ocurrió, porque una hoja suelta viaja
  // sola y sin esa línea parecería un documento.
  entrevista:{titulo:'Las razones del adversario',tipo:'Entrevista imaginada con Norberto Bobbio, a la manera de Iñaki Gabilondo',etiqueta:'<strong>⚠️ Entrevista imaginada: el encuentro nunca ocurrió.</strong> La escribió el Proyecto Educativo F.A.R.O. a la manera de Iñaki Gabilondo («Hoy por Hoy», Cadena SER, 1986 a 2005). Norberto Bobbio (Turín, 1909-2004) es real, toda obra, fecha y cifra que aquí se le pone en la boca es real y comprobable, y lo único inventado es la conversación, al modo del viejo género radiofónico de las entrevistas imposibles. Ejercicio de estilo de la casa, en homenaje: no es un documento.'},
  gala:{titulo:'Los nombres que muerden',tipo:'Conversación imaginada: Jesús Quintero con Antonio Gala (El Loco de la Colina)',etiqueta:'<strong>⚠️ Conversación imaginada: esta charla nunca ocurrió.</strong> Jesús Quintero (1940-2022) y Antonio Gala (1930-2023) se entrevistaron varias veces en la realidad, pero esta pieza es un ejercicio de estilo de la casa, en homenaje: las voces se imitan, toda obra, fecha y cifra citada dentro es real y comprobable, y lo único inventado es la conversación.'},
};
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · El mapa de las familias · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#4a1f09;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#78350f;border-bottom:1.5pt solid #78350f;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #78350f;background:#fdf3e7;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#4a1f09;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#78350f;background:#fdf3e7;border-left:3pt solid #78350f;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#78350f;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🧬 El mapa de las familias${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🧬 Ruta de las Gafas a la Vista · Etapa 3 de 7</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +`<div class="etiqueta">${meta.etiqueta||'<strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.'}</div>`
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  _abreImpresion(_hojaImpresa(meta.titulo,cuerpo,' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🧬 Ruta de las Gafas a la Vista · Etapa 3 de 7</span><span>Las cinco lecturas 📖</span></div>`
    +`<h1>Las cinco lecturas de «El mapa de las familias»</h1><div class="tipo">Un cuento, un capítulo de caballerías, un ensayo y dos entrevistas imaginadas, sobre el mismo mapa de familias</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco textos <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>: los escribió el Proyecto Educativo F.A.R.O. imitando sus voces, y se declaran como pastiche. Las dos entrevistas son además <strong>ficticias y se declaran</strong>: los encuentros <strong>nunca ocurrieron</strong>; Norberto Bobbio, Iñaki Gabilondo, Jesús Quintero y Antonio Gala son personas reales y lo único inventado es la conversación. Regla extra de la casa: <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las cinco lecturas',cuerpo,' · Las cinco lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🧬 Ruta de las Gafas a la Vista · Etapa 3 de 7</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las cinco lecturas</h1><div class="tipo">El mapa de las familias · 25 de comprensión lectora, 10 de completar y 10 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los cinco textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco textos son <strong>ejercicios de estilo de la casa</strong>: tres pastiches declarados (no obra de Borges, Cervantes ni Harari) y dos entrevistas imaginadas cuyos encuentros <strong>nunca ocurrieron</strong>.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (25 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (10 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (10 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue recorriendo el mapa!','¡Muy buen trabajo!','¡Aprendiz de cartógrafo!','¡Ya distingues la mejor versión del muñeco!','¡Dibujas las siete familias sin caricatura!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🧬 ¡'+name+' completó la Etapa 3 de la Ruta de las Gafas a la Vista (El mapa de las familias)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

